function UIBattleFlipCardNode:SetPlayer(playerDesc, isOwner)
    local avatarId = checkInt(playerDesc.avatar)
    local avatarFrameId = checkInt(playerDesc.avatarFrame)
    self.LT_PlayerHead:FreshAvatarFrame(avatarId, avatarFrameId)
    KTool.SetActive(self.RT_PlayerHeadOwnerIcon, isOwner == 1)
end

function UIBattleFlipCardNode:ShowFlip(reward, playerDesc, isOwner)
    self:SetReward(reward)
    self:SetPlayer(playerDesc, isOwner)
